import{_ as r,o as i,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse(`{"title":"Dépannage Zendure pour Home Assistant","description":"Dépannage en cas de problèmes de connexion avec l'intégration Zendure pour Home Assistant.","frontmatter":{"title":"Dépannage Zendure pour Home Assistant","description":"Dépannage en cas de problèmes de connexion avec l'intégration Zendure pour Home Assistant."},"headers":[],"relativePath":"fr/collection/zendure-ha/fehlersuche.md","filePath":"fr/collection/zendure-ha/fehlersuche.md","lastUpdated":1793447386000}`),t={name:"fr/collection/zendure-ha/fehlersuche.md"};function l(o,e,d,s,u,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<p><a id="zendure-ha-depannage"></a><a id="orientation-actuelle"></a></p><h1 id="fehlersuche" tabindex="-1">Dépannage <a class="header-anchor" href="#fehlersuche" aria-label="Permalink to &quot;Dépannage {#fehlersuche}&quot;">​</a></h1><h2 id="grundcheck" tabindex="-1">Vérifications de base <a class="header-anchor" href="#grundcheck" aria-label="Permalink to &quot;Vérifications de base {#grundcheck}&quot;">​</a></h2><ol><li>Mettre à jour l&#39;intégration vers la dernière version.</li><li>Redémarrer Home Assistant.</li><li>Vérifier que le jeton (token) de l&#39;application Zendure provient bien du compte principal.</li><li>Vérifier que les appareils sont visibles dans l&#39;application Zendure.</li><li>Activer la journalisation de débogage (debug logging) pour l&#39;intégration Zendure.</li><li>En cas d&#39;utilisation de MQTT local : vérifier l&#39;adresse du broker, l&#39;identifiant, le mot de passe, ainsi que le SSID et le mot de passe du réseau Wi-Fi.</li></ol><h2 id="haufige-fehlermeldungen" tabindex="-1">Messages d&#39;erreur fréquents <a class="header-anchor" href="#haufige-fehlermeldungen" aria-label="Permalink to &quot;Messages d&#39;erreur fréquents {#haufige-fehlermeldungen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Signification / Action</th></tr></thead><tbody><tr><td>Jeton (Token) invalide</td><td>Copiez à nouveau le jeton depuis l&#39;application Zendure</td></tr><tr><td>Aucun appareil trouvé</td><td>Vérifiez si le compte Zendure ou la région sont corrects</td></tr><tr><td>Aucun serveur MQTT renvoyé</td><td>Vérifiez la configuration MQTT (locale ou cloud) dans l&#39;application Zendure</td></tr><tr><td>Aucun groupe de protection (Fuse Group)</td><td>Définissez un groupe de protection (Fuse Group)</td></tr><tr><td>HEMS</td><td>L&#39;appareil est contrôlé par un système HEMS et ne peut pas être géré librement par le gestionnaire</td></tr></tbody></table><h2 id="hyper2000-legacy-gerate" tabindex="-1">Hyper2000 / Appareils d&#39;ancienne génération (Legacy) <a class="header-anchor" href="#hyper2000-legacy-gerate" aria-label="Permalink to &quot;Hyper2000 / Appareils d&#39;ancienne génération (Legacy) {#hyper2000-legacy-gerate}&quot;">​</a></h2><p>En cas de problèmes de connexion, le wiki officiel recommande :</p><ol><li>Activer la journalisation de débogage (Debug-Logging).</li><li>Supprimer l&#39;entrée de l&#39;intégration.</li><li>Redémarrer l&#39;appareil.</li><li>Mettre à jour l&#39;intégration.</li><li>Ajouter à nouveau l&#39;intégration à l&#39;aide du jeton (token) de l&#39;application Zendure.</li><li>Activer la journalisation MQTT.</li><li>Configurer le MQTT local en incluant tous les champs.</li><li>Tester d&#39;abord <code>cloud</code> comme mode de connexion.</li><li>Définir le « Fuse Group » (groupe de protection).</li><li>Vérifier si l&#39;appareil possède une adresse MAC Bluetooth.</li><li>Attendre au moins 10 minutes, car les mises à jour via Bluetooth peuvent être différées.</li></ol><h2 id="wenn-das-gerat-nicht-reagiert" tabindex="-1">Si l&#39;appareil ne répond pas <a class="header-anchor" href="#wenn-das-gerat-nicht-reagiert" aria-label="Permalink to &quot;Si l&#39;appareil ne répond pas {#wenn-das-gerat-nicht-reagiert}&quot;">​</a></h2><ul><li>Sélectionner le mode de fonctionnement <code>Manuelle Leistungsregelung</code>.</li><li>Modifier <code>Manuelle Leistung</code> à titre de test (par exemple, régler sur 300 W, puis sur 400 W).</li><li>Tester ensuite <code>Smarte Leistungsregelung</code>.</li><li>En l&#39;absence de réaction, sauvegarder le journal de débogage (debug log) complet.</li></ul><p>Wiki original :</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Troubleshooting" target="_blank" rel="noreferrer">Dépannage</a></li></ul>',13)])])}const h=r(t,[["render",l]]);export{g as __pageData,h as default};
